using System;
using System.Collections.Generic;
using UnityEngine;

namespace ResolverMaster.Games.TrafficJam.View
{
    /// <summary>
    /// Provisional Traffic jam art generated by code (TJ-001), cartoon style with black outlines and round shapes; the final drawings will
    /// come later. Vehicles are seen from above, drawn pointing up (front = top of the texture) in layers: wheels (dark, peeking out at
    /// the sides), body (white with a black outline: tinted with the vehicle color), the stripes of a target car (white, tinted), details
    /// (windows, lights; not tinted). Trucks are 3 cells long (cab + cargo box). Also: the road-works barrier (striped plate), the exit gate
    /// (tinted with its car color) with its chevrons, the arrow of the light bulb, a plain tile (no chapter theme).
    /// Every texture has <see cref="TrafficJamConfig.spritePixelsPerCell"/> pixels per cell (never drawn bigger than that). Cached per set
    /// of config values for the whole run.
    /// </summary>
    public sealed class TrafficSprites
    {
        static readonly Dictionary<string, TrafficSprites> s_cache = new Dictionary<string, TrafficSprites>();

        public Sprite CarWheels, CarBody, CarDetails, CarStripes;
        public Sprite TruckWheels, TruckBody, TruckDetails;
        public Sprite Barrier, GateBody, GateArrows, Arrow, Tile;

        public static TrafficSprites For(TrafficJamConfig cfg)
        {
            string key = string.Join("|", cfg.spritePixelsPerCell, cfg.vehicleInset, cfg.vehicleCorner, cfg.outline, cfg.glassColor, cfg.wheelColor,
                cfg.barrierColorA, cfg.barrierColorB);
            if (s_cache.TryGetValue(key, out var cached) && cached.IsAlive) return cached;
            var s = new TrafficSprites();
            s.Generate(cfg);
            s_cache[key] = s;
            return s;
        }

        bool IsAlive => CarWheels != null && CarBody != null && CarDetails != null && CarStripes != null && TruckWheels != null && TruckBody != null &&
                        TruckDetails != null && Barrier != null && GateBody != null && GateArrows != null && Arrow != null && Tile != null;

        void Generate(TrafficJamConfig cfg)
        {
            int ppc = Mathf.Clamp(cfg.spritePixelsPerCell, 32, 512);
            float inset = cfg.vehicleInset, r = cfg.vehicleCorner, ol = cfg.outline;
            Color32 glass = cfg.glassColor, wheel = cfg.wheelColor;
            var light = new Color(1f, 0.96f, 0.78f, 1f);

            // ---- car: 1 x 2 cells
            float CarSdf(Vector2 p) => RoundBox(p, new Vector2(0.5f, 1f), new Vector2(0.5f - inset, 1f - inset), r);
            CarWheels = Draw("tj_car_wheels", ppc, 1, 2, p =>
            {
                float d = float.MaxValue;
                foreach (float y in new[] { 0.42f, 1.58f })
                foreach (float x in new[] { inset + 0.015f, 1f - inset - 0.015f })
                    d = Mathf.Min(d, RoundBox(p, new Vector2(x, y), new Vector2(0.075f, 0.16f), 0.05f));
                return Fill(d, ol, wheel, ppc);
            });
            CarBody = Draw("tj_car_body", ppc, 1, 2, p =>
            {
                float d = CarSdf(p);
                float roof = RoundBox(p, new Vector2(0.5f, 0.98f), new Vector2(0.3f, 0.4f), 0.14f);
                float g = Mathf.Lerp(1f, 0.86f, Smooth(-0.03f, 0.03f, roof));   // lighter roof, a little darker hood and boot
                return Shape(d, ol, new Color(g, g, g, 1f), ppc);
            });
            CarStripes = Draw("tj_car_stripes", ppc, 1, 2, p =>
            {
                float d = Mathf.Min(RoundBox(p, new Vector2(0.415f, 1f), new Vector2(0.035f, 0.8f), 0.03f),
                    RoundBox(p, new Vector2(0.585f, 1f), new Vector2(0.035f, 0.8f), 0.03f));
                return Coverage(d, ppc, Color.white);
            });
            CarDetails = Draw("tj_car_details", ppc, 1, 2, p =>
            {
                var c = new Color(0, 0, 0, 0);
                // windscreen at the front (top), rear window, two headlights
                c = Over(c, Fill(RoundBox(p, new Vector2(0.5f, 1.46f), new Vector2(0.31f, 0.13f), 0.09f), ol * 0.7f, glass, ppc));
                c = Over(c, Fill(RoundBox(p, new Vector2(0.5f, 0.44f), new Vector2(0.28f, 0.085f), 0.07f), ol * 0.7f, glass, ppc));
                c = Over(c, Coverage(Seg(p, new Vector2(0.3f, 1.42f), new Vector2(0.46f, 1.54f)) - 0.018f, ppc, new Color(1, 1, 1, 0.45f)));
                foreach (float x in new[] { 0.29f, 0.71f })
                    c = Over(c, Fill((p - new Vector2(x, 2f - inset - 0.075f)).magnitude - 0.055f, ol * 0.6f, light, ppc));
                return c;
            });

            // ---- truck: 1 x 3 cells, cab at the front (top) and the cargo box
            TruckWheels = Draw("tj_truck_wheels", ppc, 1, 3, p =>
            {
                float d = float.MaxValue;
                foreach (float y in new[] { 0.42f, 1.32f, 2.5f })
                foreach (float x in new[] { inset + 0.015f, 1f - inset - 0.015f })
                    d = Mathf.Min(d, RoundBox(p, new Vector2(x, y), new Vector2(0.075f, 0.16f), 0.05f));
                return Fill(d, ol, wheel, ppc);
            });
            TruckBody = Draw("tj_truck_body", ppc, 1, 3, p =>
            {
                float cab = RoundBox(p, new Vector2(0.5f, 2.56f), new Vector2(0.5f - inset - 0.02f, 0.44f - inset * 0.5f), r);
                float box = RoundBox(p, new Vector2(0.5f, 1.08f), new Vector2(0.5f - inset, 1.08f - inset), 0.1f);
                float d = Mathf.Min(cab, box);
                float g = box < cab ? 0.9f : 1f;   // the cargo box a little darker than the cab
                return Shape(d, ol, new Color(g, g, g, 1f), ppc);
            });
            TruckDetails = Draw("tj_truck_details", ppc, 1, 3, p =>
            {
                var c = new Color(0, 0, 0, 0);
                c = Over(c, Fill(RoundBox(p, new Vector2(0.5f, 2.62f), new Vector2(0.3f, 0.12f), 0.08f), ol * 0.7f, glass, ppc));
                c = Over(c, Coverage(Seg(p, new Vector2(0.3f, 2.58f), new Vector2(0.46f, 2.7f)) - 0.018f, ppc, new Color(1, 1, 1, 0.45f)));
                // ribs across the cargo box
                foreach (float y in new[] { 0.5f, 0.95f, 1.4f, 1.85f })
                    c = Over(c, Coverage(Seg(p, new Vector2(inset + 0.12f, y), new Vector2(1f - inset - 0.12f, y)) - 0.012f, ppc, new Color(0, 0, 0, 0.22f)));
                foreach (float x in new[] { 0.29f, 0.71f })
                    c = Over(c, Fill((p - new Vector2(x, 3f - inset - 0.08f)).magnitude - 0.055f, ol * 0.6f, light, ppc));
                return c;
            });

            // ---- barrier: a striped plate (amber and charcoal), not tinted
            Color32 a = cfg.barrierColorA, b = cfg.barrierColorB;
            Barrier = Draw("tj_barrier", ppc, 1, 1, p =>
            {
                float d = RoundBox(p, new Vector2(0.5f, 0.5f), new Vector2(0.4f, 0.4f), 0.12f);
                float band = Mathf.Repeat((p.x + p.y) / 0.25f, 1f);
                return Fill(d, ol, band < 0.5f ? (Color)a : (Color)b, ppc);
            });

            // ---- exit gate (2:1, the wide side along the edge): white body (tinted with the car color), white chevrons pointing out (up)
            GateBody = Draw("tj_gate_body", ppc, 2, 1, p => Shape(RoundBox(p, new Vector2(1f, 0.5f), new Vector2(0.96f, 0.46f), 0.24f), ol * 1.2f, Color.white, ppc));
            GateArrows = Draw("tj_gate_arrows", ppc, 2, 1, p =>
            {
                float d = Mathf.Min(Chevron(p, new Vector2(0.62f, 0.5f), 0.2f), Chevron(p, new Vector2(1.38f, 0.5f), 0.2f));
                return Fill(d - 0.035f, ol * 0.8f, Color.white, ppc);
            });

            // ---- the light bulb arrow (points up), white with a black outline
            Arrow = Draw("tj_hint_arrow", ppc, 1, 1, p =>
            {
                float head = Mathf.Max(Mathf.Abs(p.x - 0.5f) * 1.1f + (p.y - 0.86f) * 0.62f, 0.5f - p.y);   // triangle
                float shaft = RoundBox(p, new Vector2(0.5f, 0.32f), new Vector2(0.11f, 0.2f), 0.05f);
                return Fill(Mathf.Min(head, shaft), ol * 1.1f, Color.white, ppc);
            });

            Tile = Draw("tj_tile", ppc, 1, 1, p => Fill(RoundBox(p, new Vector2(0.5f, 0.5f), new Vector2(0.46f, 0.46f), 0.12f), 0f, new Color(0.9f, 0.9f, 0.9f, 1f), ppc));
        }

        // ------------------------------------------------------------------ raster helpers (coordinates in cells, y up)

        /// <summary>A V pointing up with its tip at the top of a box of half-size <paramref name="h"/> around <paramref name="c"/>.</summary>
        static float Chevron(Vector2 p, Vector2 c, float h)
        {
            var q = p - c;
            q.x = Mathf.Abs(q.x);
            // two thick segments from the tip down to the sides
            return Seg(new Vector2(q.x, q.y), new Vector2(0f, h * 0.7f), new Vector2(h * 1.1f, -h * 0.5f)) - h * 0.22f;
        }

        static float RoundBox(Vector2 p, Vector2 centre, Vector2 half, float r)
        {
            float qx = Mathf.Abs(p.x - centre.x) - (half.x - r);
            float qy = Mathf.Abs(p.y - centre.y) - (half.y - r);
            return new Vector2(Mathf.Max(qx, 0), Mathf.Max(qy, 0)).magnitude + Mathf.Min(Mathf.Max(qx, qy), 0) - r;
        }

        static float Seg(Vector2 p, Vector2 a, Vector2 b)
        {
            var ab = b - a;
            float t = Mathf.Clamp01(Vector2.Dot(p - a, ab) / Mathf.Max(1e-6f, ab.sqrMagnitude));
            return (p - (a + ab * t)).magnitude;
        }

        static float Smooth(float a, float b, float x) => Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(a, b, x));

        /// <summary>An anti-aliased shape: black outline of width <paramref name="outline"/> inside its edge, <paramref name="body"/> inside.</summary>
        static Color Shape(float d, float outline, Color body, int ppc)
        {
            float px = 1f / ppc;
            float alpha = Mathf.Clamp01(0.5f - d / px);
            if (alpha <= 0f) return new Color(0, 0, 0, 0);
            float inner = Mathf.Clamp01(0.5f - (d + outline) / px);
            var c = Color.Lerp(Color.black, body, inner);
            c.a = alpha * body.a;
            return c;
        }

        static Color Fill(float d, float outline, Color body, int ppc) => Shape(d, outline, body, ppc);

        /// <summary>Plain coverage of a shape in one color (no outline).</summary>
        static Color Coverage(float d, int ppc, Color color)
        {
            float alpha = Mathf.Clamp01(0.5f - d * ppc) * color.a;
            return new Color(color.r, color.g, color.b, alpha);
        }

        /// <summary>Alpha compositing of <paramref name="top"/> over <paramref name="under"/>.</summary>
        static Color Over(Color under, Color top)
        {
            float a = top.a + under.a * (1f - top.a);
            if (a <= 0f) return new Color(0, 0, 0, 0);
            var c = (top * top.a + under * under.a * (1f - top.a)) / a;
            c.a = a;
            return c;
        }

        static Sprite Draw(string name, int ppc, int cellsWide, int cellsTall, Func<Vector2, Color> pixel)
        {
            int w = ppc * cellsWide, h = ppc * cellsTall;
            var tex = new Texture2D(w, h, TextureFormat.RGBA32, true)
            {
                name = name, wrapMode = TextureWrapMode.Clamp, filterMode = FilterMode.Trilinear, hideFlags = HideFlags.HideAndDontSave,
            };
            var px = new Color32[w * h];
            float step = 1f / ppc;
            for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                px[y * w + x] = pixel(new Vector2((x + 0.5f) * step, (y + 0.5f) * step));
            tex.SetPixels32(px);
            tex.Apply(true, true);
            var sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect);
            sprite.name = name;
            sprite.hideFlags = HideFlags.HideAndDontSave;
            return sprite;
        }
    }
}
